        ('20260831180000', 'security_hardening', true),
        ('20260831200000', 'messages_rls_hardening', true),
        ('20260901120000', 'admin1_identity_and_audit', true),
        ('20260901140000', 'admin2_coach_read_api', true),
        ('20260903021342', 'admin3_student_read_api', true),
        ('20260906214127', 'admin4a_coach_invites', true),
        ('20260906235216', 'admin4a1_fix_expired_invite_revoke', true),
        ('20260907161315', 'account_access_control_phase_a', true),
        ('20260907183000', 'account_access_control_phase_b', true),
        ('20260908000000', 'account_access_control_phase_b1_anon_grant_fix', true),
        ('20260908010000', 'account_access_control_phase_c0_grant_hardening', true),
        ('20260911142144', 'account_access_control_phase_c2_rls', true),
        ('20260911171437', 'admin4b_coach_student_access_status', true),
        ('20260915120000', 'coach_data_sync_phase1_additive', true),
        ('20260929230000', 'student_portal_rpc', true),
        ('20260930120000', 'drop_student_read_coach_data', true),
        ('20260930150000', 'drop_student_read_coach', true),
        ('20261001120000', 'student_pending_invite', true),
        ('20261122120000', 'student_portal_notices_overrides', true)
    ), expected_fn(sig, expected) as (values
        ('public.get_my_student_portal()', '9cecae2c6aee26da2501f3efcbc8410d / secdef=true / owner=postgres'),
        ('public.portal_filter_id_array(jsonb,text[])', '03e0a98af93d7b3dc4efbbffb710af44 / secdef=false / owner=postgres'),
        ('public._my_pending_student_invites()', '64c59845331b78e137379d70a13b12ba / secdef=false / owner=postgres'),
        ('public.get_my_account_status()', '32e803789e1870ec37fba413d93e8199 / secdef=true / owner=postgres'),
        ('public.accept_my_pending_invite()', 'eed6b43f5d38cf8dab805f66d133934a / secdef=true / owner=postgres'),
        ('public.portal_class_overrides(jsonb)', 'd332ef7020d1b862e017e4d44bb69048 / secdef=false / owner=postgres'),
        ('public.portal_class_notices(jsonb,text[])', '966e5f59d66208f1935f69d3b25778b7 / secdef=false / owner=postgres')
    ), expected_grant(sig, role_name, expected) as (values
        ('public.get_my_student_portal()', 'anon', 'false'),
        ('public.get_my_student_portal()', 'authenticated', 'true'),
        ('public.portal_class_overrides(jsonb)', 'anon', 'false'),
        ('public.portal_class_overrides(jsonb)', 'authenticated', 'false'),
        ('public.portal_class_notices(jsonb,text[])', 'anon', 'false'),
        ('public.portal_class_notices(jsonb,text[])', 'authenticated', 'false')
    ), checks as (
      select 1 as ord, 'history' as section, 'primary key on version' as item, 'true' as expected,
             (exists (select 1 from pg_constraint where conrelid = 'supabase_migrations.schema_migrations'::regclass and contype = 'p'))::text as actual
      union all
      select 2, 'history', h.version || ' ' || h.name, case when h.present then 'present' else 'absent' end,
             case when m.version is null then 'absent' else 'present' end
      from expected_history h left join supabase_migrations.schema_migrations m on m.version = h.version
      union all
      select 3, 'history', 'versions not in the repo', '0',
             (select count(*) from supabase_migrations.schema_migrations m where m.version not in (select version from expected_history))::text
      union all
      select 4, 'policy', p.tbl || '.' || p.pol, 'absent',
             case when exists (select 1 from pg_policies where schemaname = 'public' and tablename = p.tbl and policyname = p.pol) then 'present' else 'absent' end
      from (values ('coach_data', 'student_read_coach_data'), ('coaches', 'student_read_coach')) as p(tbl, pol)
      union all
      select 5, 'function', f.sig, f.expected,
             coalesce(md5(p.prosrc) || ' / secdef=' || p.prosecdef::text || ' / owner=' || pg_get_userbyid(p.proowner), 'missing')
      from expected_fn f left join pg_proc p on p.oid = to_regprocedure(f.sig)
      union all
      select 7, 'grant', g.sig || ' execute by ' || g.role_name, g.expected,
             case when to_regprocedure(g.sig) is null then 'missing' else has_function_privilege(g.role_name, g.sig, 'execute')::text end
      from expected_grant g
    )
    select ord, section, item, expected, actual, expected = actual as ok from checks order by ord, item loop
    if not r.ok then
      v_bad := v_bad || E'\n  ' || r.section || ' ' || r.item || ': expected ' || r.expected || ', found ' || r.actual;
    end if;
  end loop;
  if v_bad <> '' then
    raise exception '03_apply_migration_d (post): aborted, nothing was changed.%', v_bad;
  end if;
end
$guard$;

commit;
